{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Tropisetron, an N-methyl-tropane aromatic ester very close in scaffold to the query, showed high brain penetration in mice with a brain/plasma ratio of 2.5, directly supporting meaningful CNS access for this basic ester chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A tropane-based ester radiotracer ([18F]MCL-322) showed rapid brain entry and high striatal uptake (3.23% ID/g at 5 min) in rats, demonstrating that N-methyl-tropane esters with aromatic substituents cross the BBB efficiently.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "N-methylpiperidin-4-yl 4-iodobenzoate, a basic azacyclic aryl ester, entered the rat brain after intravenous injection and labeled BChE-rich regions, supporting brain penetration of ionizable basic esters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A small N-methylpyrrolidine ester showed high, rapid striatal uptake in rat PET imaging, indicating that basic amine esters of similar size and polarity can readily cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A tropane ester with an aromatic group showed approximately 540% SUV in the caudate of cynomolgus monkeys, confirming high brain uptake for this scaffold in a primate species.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: despite the strong basic amine and low predicted passive permeability, multiple close structural analogs—especially N-methyl-tropane aryl esters—show high brain uptake in rodents and primates, indicating meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Ester hydrolysis could alter the in vivo exposure profile, though the parent ester is expected to penetrate.",
    "Efflux transporter involvement was not directly measured for the query.",
    "Human data are available only for close analogs, not the exact compound."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

